#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_VARS 676

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    int grid[105][105];
    long long row_sum[105];
    long long col_sum[105];

    bool present[MAX_VARS] = {false};
    bool known[MAX_VARS] = {false};
    long long val[MAX_VARS] = {0};
    int total_vars = 0;

    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            char s[4];
            scanf("%s", s);
            int id = (s[0] - 'a') * 26 + (s[1] - 'a');
            grid[i][j] = id;
            if (!present[id]) {
                present[id] = true;
                total_vars++;
            }
        }
        scanf("%lld", &row_sum[i]);
    }

    for (int j = 0; j < C; j++) {
        scanf("%lld", &col_sum[j]);
    }

    int remaining_vars = total_vars;

    while (remaining_vars > 0) {
        bool progress = false;

        // Tentar resolver pelas linhas
        for (int i = 0; i < L; i++) {
            int unknown_id = -1;
            int unknown_count = 0;
            long long known_sum = 0;
            bool multiple_unknowns = false;

            for (int j = 0; j < C; j++) {
                int id = grid[i][j];
                if (known[id]) {
                    known_sum += val[id];
                } else {
                    if (unknown_id == -1) {
                        unknown_id = id;
                        unknown_count = 1;
                    } else if (unknown_id == id) {
                        unknown_count++;
                    } else {
                        multiple_unknowns = true;
                        break;
                    }
                }
            }

            if (!multiple_unknowns && unknown_id != -1) {
                val[unknown_id] = (row_sum[i] - known_sum) / unknown_count;
                known[unknown_id] = true;
                remaining_vars--;
                progress = true;
                break;
            }
        }

        if (progress) continue;

        // Tentar resolver pelas colunas
        for (int j = 0; j < C; j++) {
            int unknown_id = -1;
            int unknown_count = 0;
            long long known_sum = 0;
            bool multiple_unknowns = false;

            for (int i = 0; i < L; i++) {
                int id = grid[i][j];
                if (known[id]) {
                    known_sum += val[id];
                } else {
                    if (unknown_id == -1) {
                        unknown_id = id;
                        unknown_count = 1;
                    } else if (unknown_id == id) {
                        unknown_count++;
                    } else {
                        multiple_unknowns = true;
                        break;
                    }
                }
            }

            if (!multiple_unknowns && unknown_id != -1) {
                val[unknown_id] = (col_sum[j] - known_sum) / unknown_count;
                known[unknown_id] = true;
                remaining_vars--;
                progress = true;
                break;
            }
        }
    }

    // Imprimir as variáveis em ordem alfabética
    for (int id = 0; id < MAX_VARS; id++) {
        if (present[id]) {
            char c1 = (char)('a' + id / 26);
            char c2 = (char)('a' + id % 26);
            printf("%c%c %lld\n", c1, c2, val[id]);
        }
    }

    return 0;
}
```

